# Dense gesture anchors measured from additional native-frame inspection.
def hand_variant(points,dx,dy,elbow=0):
 out=[]
 for x,y in points:
  w=max(0,min(1,(500-x)/220));q=max(0,min(1,(y-620)/140))
  out.append((x+dx*w,y+dy*w+elbow*(1-w)*q))
 return out
