@lru_cache(maxsize=128)
def distance(component,key):
 poly=COMPONENTS[component][key];m=np.zeros((H,W),np.uint8);cv2.fillPoly(m,[np.asarray(poly,np.int32)],255)
 return cv2.distanceTransform(m,cv2.DIST_L2,3)-cv2.distanceTransform(255-m,cv2.DIST_L2,3)
COMPONENTS={'head':HEAD,'body':BODY,'left':LEFT,'right':RIGHT}
def prior(frame):
 out=np.zeros((H,W),np.uint8)
 for name,keys in COMPONENTS.items():
  lo=max((k for k in keys if k<=frame),default=min(keys));hi=min((k for k in keys if k>=frame),default=max(keys));u=0 if lo==hi else(frame-lo)/(hi-lo)
  mask=np.uint8((1-u)*distance(name,lo)+u*distance(name,hi)>0)*255;out=np.maximum(out,mask)
 return out

def clear_arm_gap(mask,frame):
 # Independently traced visible motorcycle hole between hanging left glove and trousers.
 if frame<60 or 161<=frame<=165:return mask
 poly=[(339,866),(342,882),(345,909),(346,940),(348,965),(342,979),(334,971),(333,960),(325,947),(319,933),(322,915),(326,896),(334,878)]
 hole=np.zeros((H,W),np.uint8);cv2.fillPoly(hole,[np.asarray(poly,np.int32)],255)
 if 97<=frame<=99:hole[:920]=0
 # Preserve soft matte transition only at this new inner boundary.
 inv=255-cv2.GaussianBlur(hole,(3,3),.6)
 return np.minimum(mask,inv)

def extract(im,frame):
 m=prior(frame);radius=8 if (92<=frame<=112 or 154<=frame<=176) else 5
 er=cv2.erode(m,np.ones((23,23),np.uint8));di=cv2.dilate(m,np.ones((radius*2+1,radius*2+1),np.uint8))
 labels=np.zeros((H,W),np.uint8);labels[di>0]=2;labels[m>0]=3;labels[er>0]=1
 # Restrict motorcycles at lower left/right to a narrow, hand-annotated edge band.
 bg=np.zeros((1,65));fg=np.zeros((1,65));cv2.grabCut(im,labels,None,bg,fg,2,cv2.GC_INIT_WITH_MASK)
 mask=np.uint8((labels==1)|(labels==3))*255
 return clear_arm_gap(cv2.GaussianBlur(mask,(3,3),.6),frame)

def qa(video,out):
 cap=cv2.VideoCapture(str(video));fs=[0,48,72,96,104,108,120,144,156,160,164,168,192,216,239];contact=np.zeros((1280,1200,3),np.uint8)
 for i,f in enumerate(fs):
  path=out/f'{f:04}.png'
  if not path.exists():continue
  cap.set(1,f);ok,im=cap.read()
  if not ok:continue
  a=cv2.imread(str(path),0).astype(float)[:,:,None]/255;bg=np.full_like(im,(180,80,120));comp=np.uint8(im*a+bg*(1-a));thumb=cv2.resize(comp,(240,426));cv2.putText(thumb,str(f),(5,20),cv2.FONT_HERSHEY_SIMPLEX,.6,(0,255,255),1)
  contact[(i//5)*426:(i//5+1)*426,(i%5)*240:(i%5+1)*240]=thumb
 cv2.imwrite(str(out/'qa-contact.jpg'),contact);cap.release()
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--video',type=Path,default=ROOT/'media/source.mp4');ap.add_argument('--out',type=Path,default=ROOT/'assets/subject_masks');ap.add_argument('--frames',type=int,nargs='*');args=ap.parse_args();args.out.mkdir(exist_ok=True,parents=True);cv2.setNumThreads(2);cv2.setRNGSeed(330494)
 cap=cv2.VideoCapture(str(args.video))
 for f in args.frames or range(240):
  cap.set(1,f);ok,im=cap.read()
  if not ok:raise RuntimeError(f)
  cv2.imwrite(str(args.out/f'{f:04}.png'),extract(im,f))
  if f%24==0:print(f,flush=True)
 cap.release();qa(args.video,args.out)
 data={'source':str(args.video),'sha256':hashlib.sha256(args.video.read_bytes()).hexdigest(),'native_resolution':[W,H],'fps':24,'frames':sorted(int(p.stem)for p in args.out.glob('[0-9][0-9][0-9][0-9].png')),'method':'fresh manually annotated component polygons, signed-distance interpolation,2iteration boundedGrabCut,0.6px feather','components':COMPONENTS,'preservation':'SourceRGB untouched. Pilot only, motorcycle excluded.','limitations':['Subpixel motionblur during hand lift/lowering approximated by0.6px feather; not groundtruth alpha.','Black glove touching black motorcycle requires constrainedmanual edge; inspect before extreme background replacement.','Boots are outside source frame; no unseen body parts invented.']}
 (args.out/'provenance.json').write_text(json.dumps(data,indent=2))
